input.script:
() => {
  const input = document.querySelector('input[aria-label="搜索国家/地区"]');
  if (input) {
    input.focus();
    input.value = '';
    input.dispatchEvent(new Event('input', { bubbles: true }));
    return 'cleared';
  }
  return 'no input';
}

() => {
  // Find all menu items in the dropdown
  const items = document.querySelectorAll('[role="menuitemradio"]');
  const result = [];
  items.forEach((item, index) => {
    const text = item.textContent.trim();
    result.push({ index, text });
  });
  return result;
}

() => {
  // Find all LI elements in the dropdown
  const items = document.querySelectorAll('li');
  let usa = null;
  items.forEach((item) => {
    if (item.textContent.trim() === 'United States') {
      usa = item;
    }
  });
  if (usa) {
    usa.click();
    return 'clicked United States';
  }
  return 'not found';
}

() => {
  // Find the search input
  const input = document.querySelector('input[aria-label="Search locations"]');
  if (!input) return 'input not found';

  // Set value and dispatch event
  const nativeInputValueSetter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
  nativeInputValueSetter.call(input, 'United States');
  input.dispatchEvent(new Event('input', { bubbles: true }));

  // Wait a bit and find the filtered option
  return new Promise((resolve) => {
    setTimeout(() => {
      const items = document.querySelectorAll('li');
      let found = null;
      items.forEach((item) => {
        if (item.textContent.trim() === 'United States') {
          found = item.querySelector('div') || item;
          found.click();
        }
      });
      resolve(found ? 'clicked United States' : 'not found');
    }, 500);
  });
}

() => {
  // Find the search input at the top of the dropdown
  const input = document.querySelector('input[placeholder="Search locations"]');
  if (!input) {
    // Try alternative
    const inputs = document.querySelectorAll('input');
    const inputList = [];
    inputs.forEach((i, idx) => inputList.push({ idx, placeholder: i.placeholder, aria: i.getAttribute('aria-label') }));
    return JSON.stringify(inputList);
  }

  input.focus();
  input.value = 'United States';
  input.dispatchEvent(new Event('input', { bubbles: true }));
  return 'set value to United States';
}
